+            super(weight);
+            this.scorer = scorer;
+            this.valueFetcher = valueFetcher;
+            this.field = field;
+            this.query = query;
+            twoPhase = new TwoPhaseIterator(approximation) {
+
+                @Override
+                public boolean matches() throws IOException {
