+                assertEquals(DocIdSetIterator.NO_MORE_DOCS, intervals.nextDoc());
+
+                intervals = source.intervals("body", reader.leaves().get(1));
+                assertEquals(DocIdSetIterator.NO_MORE_DOCS, intervals.nextDoc());
+            }
+        }
+    }
